def chk(g,name):
    n=30
    res={}
    for lbl,f in [('T',lambda i,j:(j,i)),('anti',lambda i,j:(29-j,29-i)),
                  ('rot90',lambda i,j:(j,29-i)),('rot270',lambda i,j:(29-j,i))]:
        m=t=0
        for i in range(n):
            for j in range(n):
                i2,j2=f(i,j)
                if 0<=i2<n and 0<=j2<n and g[i][j]!=8 and g[i2][j2]!=8:
                    t+=1; m+=g[i][j]==g[i2][j2]
        res[lbl]=(m,t)
    print(name,res)
